// One event, one letter, one named target — the executor sends the words
// the approval read, verbatim, to the address the sending lock resolved.
//
// This node does not write any of the letter. CrowdRelay composed it when
// the action was written — the words the operator approved ride in `draft`,
// and a payload without one is refused rather than filled in here.
//
// Two event types share this transport:
//  - crowdrelay.outreach.requested        — the pitch (phase, template_key)
//  - crowdrelay.outreach.reply_requested  — an answer to somebody who wrote
//    back (answers_interaction_id, no phase/template). A reply always takes
//    the mailbox: a form route is a pitch transport and never applies.
const e = $json;
const isPitch = e && e.type === 'crowdrelay.outreach.requested';
const isReply = e && e.type === 'crowdrelay.outreach.reply_requested';
if (!e || (!isPitch && !isReply) || e.version !== 1) {
  throw new Error('outreach refused: unsupported event');
}
const d = e.data ?? {};
const actionId = String(d.action_id || '').trim();
const draft = d.draft || {};
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
if (!actionId || !d.target_id || !d.target_name) {
  throw new Error('outreach refused: invalid intent');
}
if (isPitch && (!d.phase || !d.template_key)) {
  throw new Error('outreach refused: invalid intent');
}
if (isReply && !d.answers_interaction_id) {
  throw new Error('outreach reply refused: no interaction to answer');
}
// The refusal that keeps the promise: no approved words, no send. A reply's
// draft is a scaffold the operator completed — extending it here would be
// writing on the band's behalf, which is the one thing this lane forbids.
if (!subject || !body) {
  throw new Error(
    'outreach refused: no approved letter in the payload — nothing may compose one here'
  );
}
const email = String(d.contact_email || '').trim();
if (!email.includes('@')) {
  throw new Error('outreach refused: target without contact_email');
}
// A verified free-form route, when the target has one, is the address the
// pitch takes instead of Gmail. Replies never take it — a form is not an
// answer to a person.
const routes = JSON.parse($env.VIRYA_OUTREACH_FORM_ROUTES_JSON || '{}');
const route = isPitch ? (routes[String(d.target_id)] ?? null) : null;
return [{ json: {
  event_id: e.id,
  action_id: actionId,
  is_reply: isReply,
  answers_interaction_id: isReply ? Number(d.answers_interaction_id) : null,
  target_id: String(d.target_id),
  target_name: String(d.target_name),
  contact_email: email,
  phase: isPitch ? String(d.phase) : 'reply',
  template_key: isPitch ? String(d.template_key) : 'outreach.reply.v1',
  route,
  SendSubject: subject.slice(0, 220),
  SendBody: body,
}}];

const claim = $json;
const intent = $('Validate the approved letter').first().json;
// A replay of an already-finished action is a no-op, not an error.
if (claim.disposition === 'already_succeeded') return [];
// claimed is the only disposition that may reach the provider; in_flight
// and ambiguous stay claimed upstream and never send twice.
if (claim.disposition !== 'claimed' || !claim.claim_token) {
  throw new Error('Provider execution ' + (claim.disposition || 'unclaimed') + '; fail closed to prevent duplicate external side effects');
}
const route = intent.route;
if (route) {
  const u = new URL(String(route.url || ''));
  if (u.protocol !== 'https:' || route.verified!==true || route.free!==true
      || route.method!=='POST' || route.requires_login===true || route.requires_captcha===true) {
    throw new Error('Form route is not eligible for unattended execution');
  }
  // The letter travels verbatim — the form template's {{message}} receives
  // the approved body, and nothing else composes or rewrites it.
  const vars = { artist: intent.target_name, email: $env.VIRYA_OUTREACH_FROM_EMAIL || '', message: intent.SendBody };
  const resolve = v => String(v).replace(/\{\{(artist|email|message)\}\}/g, (_, k) => vars[k] ?? '');
  const fields = Object.fromEntries(Object.entries(route.fields || {}).map(([k, v]) => [k, resolve(v)]));
  const ct = route.content_type === 'application/x-www-form-urlencoded' ? 'application/x-www-form-urlencoded' : 'application/json';
  const raw = ct === 'application/x-www-form-urlencoded' ? new URLSearchParams(fields).toString() : JSON.stringify(fields);
  return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1), delivery_mode: 'form', form_url: u.toString(), form_content_type: ct, form_body: raw } }];
}
return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1), delivery_mode: 'email' } }];
